var input = JSON.parse(value);

var groupedData = {};

for (var i = 0; i < input.length; i++) {
    var innerArray = input[i];

    for (var j = 0; j < innerArray.length; j++) {
        var item = innerArray[j];
        var controllerRef = item.ethernet.controllerRef;
        var interfaceRef = item.ethernet.id;

        if (!groupedData[controllerRef]) {
            groupedData[controllerRef] = {};
        }
        groupedData[controllerRef][interfaceRef] = item.ethernet;
    }
}

return JSON.stringify(groupedData, null, 2);

